const modeloNode = $items("SQL - Modelo Mais Vendido");
const totalNode = $items("SQL - Total Geral Vendas");
const ontemNode = $items("SQL - Vendas Ontem");
const mediaNode = $items("SQL - Média 7 dias");
const historicoNode = $items("SQL - Histórico 7 dias");
const rankingNode = $items("SQL - Ranking Veículos"); // 👈 NOVO

// 🔢 Números
const hoje = Number(totalNode[0].json.total_vendas);
const ontem = Number(ontemNode[0].json.total_vendas_ontem);
const media = Number(mediaNode[0].json.media_7_dias);

// 💰 Faturamento
const faturamento_hoje = Number(totalNode[0].json.valor_total.replace(/,/g, ""));
const faturamento_ontem = Number(ontemNode[0].json.valor_total_ontem.replace(/,/g, ""));

// 🚗 Modelos
const modelo_hoje = modeloNode[0].json.modelocarro;
const modelo_ontem = ontemNode[0]?.json?.modelocarro || "";

// 📊 Regras
const vendas_baixas = hoje < media;
const faturamento_caiu = faturamento_hoje < faturamento_ontem;
const modelo_mudou = modelo_hoje !== modelo_ontem;

// 🚨 Alertas
let alertas = [];

if (vendas_baixas) alertas.push("📉 Vendas abaixo da média semanal");
if (faturamento_caiu) alertas.push("💰 Faturamento caiu");
if (modelo_mudou) alertas.push("🚗 Modelo mais vendido mudou");

// 📈 Variação
const variacao = ontem > 0 ? ((hoje - ontem) / ontem) * 100 : 0;

// 📊 HISTÓRICO
const labels = historicoNode.map(i => i.json.dia);
const dados = historicoNode.map(i => i.json.total);

// 🚗 🔥 RANKING DE VEÍCULOS (NOVO)
const ranking = rankingNode.map(item => ({
  modelo: item.json.modelo,
  total: item.json.total
}));

// 📊 CONFIGURAÇÃO DO GRÁFICO
const chartConfig = {
  type: "line",
  data: {
    labels: labels,
    datasets: [
      {
        label: "Vendas por dia",
        data: dados,
        fill: false,
        borderColor: "blue",
        borderWidth: 2,
        pointBackgroundColor: "blue",
        tension: 0.3
      }
    ]
  },
  options: {
    layout: {
      padding: {
        top: 50,
        bottom: 20
      }
    },
    plugins: {
      legend: {
        display: true,
        position: "top"
      },
      tooltip: {
        enabled: false
      },
      datalabels: {
        display: true,
        color: "black",
        anchor: "end",
        align: "top",
        offset: 10,
        font: {
          weight: "bold",
          size: 10
        }
      }
    },
    scales: {
      y: {
        beginAtZero: true
      }
    }
  },
  plugins: ["chartjs-plugin-datalabels"]
};

// 🔗 URL DO GRÁFICO
const chartUrl = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(chartConfig))}`;

// 🚨 ALERTA FINAL
const mensagem_alerta = alertas.length 
  ? alertas.join("<br>")
  : "✅ Tudo dentro do esperado";

// RELATORIO

const html = ` 
<div style="font-family: Arial; background:#f4f6f8; padding:20px;">
<h2>📊 Relatório Diário de Vendas</h2>

<p><b>Total de vendas do dia:</b> ${hoje}</p>
<p><b>Faturamento do dia:</b> R$ ${totalNode[0].json.valor_total}</p>
<p><b>Modelo mais vendido:</b> ${modelo_hoje}</p>
<p><b>Quantidade modelo mais vendido:</b> ${modeloNode[0].json.top_auto_vendido}</p>

<p><b>Alerta:</b> ${mensagem_alerta}</p>

<h3>📊 Evolução</h3>
<img src="${chartUrl}" style="width:100%" />

<h3>🏆 Ranking</h3>
<ul>
  ${ranking.map(r => `<li>${r.modelo} - ${r.total} vendas</li>`).join("")}
</ul>
`;

// 🎯 RETORNO FINAL
return [
  {
    json: {
      total_vendas: hoje,
      valor_total: totalNode[0].json.valor_total,
      modelocarro: modelo_hoje,
      top_auto_vendido: modeloNode[0].json.top_auto_vendido,
      variacao: variacao.toFixed(2),
      media_7_dias: media,
      alerta: mensagem_alerta,
      chart_url: chartUrl,
      json: html,
      ranking // 👈 NOVO DADO ADICIONADO
    }
  }
];
